        Map<String, String> permissions = new LinkedHashMap<>();
        for (String action : PERMISSION_ACTIONS) {
            permissions.put(action, settings.findBySheetIdAndKey(sheetId, permissionKey(action))
                    .map(SheetSetting::getValue).orElse(""));
        }
        return permissions;
    }

